import XCTest
@testable import AeroscopeKit

/// The watch must show the same numbers as the 3D dashboard. The fixture was
/// generated by running the web app's `computeZoneReading` for every zone,
/// preset and time step (17 × 4 × 8 = 544 rows).
final class ScenarioParityTests: XCTestCase {
    func testBundledDatasetMatchesWebDemoZones() throws {
        let dataset = try CityDataset.bundled()
        XCTAssertEqual(dataset.zones.count, 17)
        XCTAssertEqual(dataset.provenance, .demo)
        XCTAssertEqual(dataset.baselineTime, "2026-11-14T15:00:00+05:30")
        XCTAssertTrue(dataset.zones.allSatisfy { $0.geo != nil }, "every zone needs a geo anchor")
        XCTAssertEqual(dataset.zone(id: "z-cp")?.position, WorldPoint(x: 2, z: -14))
    }

    func testEveryReadingMatchesWebEngine() throws {
        let dataset = try CityDataset.bundled()
        let url = try XCTUnwrap(Bundle.module.url(forResource: "web-engine-golden", withExtension: "csv", subdirectory: "Fixtures"))
        let rows = try String(contentsOf: url, encoding: .utf8).split(separator: "\n")
        XCTAssertEqual(rows.count, 544)
        for row in rows {
            let f = row.split(separator: ",").map(String.init)
            let zone = try XCTUnwrap(dataset.zone(id: f[0]))
            let preset = try XCTUnwrap(ScenarioPresetID(rawValue: f[1]))
            let scenario = Scenario(preset: preset, timeIndex: Int(f[2])!)
            let r = ScenarioEngine.reading(for: zone, scenario: scenario, provenance: .demo)
            let context = "\(f[0]) \(f[1]) t\(f[2])"
            XCTAssertEqual(r.aqi, Int(f[3]), context)
            XCTAssertEqual(r.pm25, Int(f[4]), context)
            XCTAssertEqual(r.pm10, Int(f[5]), context)
            XCTAssertEqual(r.temperature, Int(f[6]), context)
            XCTAssertEqual(r.windSpeed, Double(f[7]), context)
            XCTAssertTrue(r.simulated)
        }
    }

    func testReadingsStayInternallyConsistent() throws {
        let dataset = try CityDataset.bundled()
        for preset in ScenarioPresetID.allCases {
            for t in 0..<8 {
                for r in ScenarioEngine.readings(for: dataset, scenario: Scenario(preset: preset, timeIndex: t)).values {
                    // Same tolerance as the web test: integer µg/m³ rounding can
                    // push the recomputed sub-index up by a few points, never down.
                    let recomputed = AQIScale.aqi(pm25: Double(r.pm25!), pm10: Double(r.pm10!))
                    XCTAssertGreaterThanOrEqual(recomputed, r.aqi)
                    XCTAssertLessThanOrEqual(recomputed - r.aqi, 3)
                    XCTAssertEqual(r.category, AQIScale.category(for: r.aqi))
                }
            }
        }
    }

    func testScenarioForClockPicksNearestStepInIST() throws {
        // 13:40 IST → 12:00 step (index 2); 23:00 IST → 00:00 step (index 6).
        let a = try XCTUnwrap(AeroscopeJSON.parseDate("2026-10-11T08:10:00Z"))
        XCTAssertEqual(Scenario.current(preset: .trafficHaze, at: a).timeIndex, 2)
        let b = try XCTUnwrap(AeroscopeJSON.parseDate("2026-10-11T17:30:00Z"))
        XCTAssertEqual(Scenario.current(preset: .trafficHaze, at: b).timeIndex, 6)
    }

    func testScenarioClampsTimeIndex() {
        XCTAssertEqual(Scenario(preset: .clearMorning, timeIndex: 42).timeIndex, 7)
        XCTAssertEqual(Scenario(preset: .clearMorning, timeIndex: -1).timeIndex, 0)
        XCTAssertEqual(Scenario.demoDefault.label, "Urban Traffic Haze · 15:00")
    }
}
